import {stations,roomJobs,createGame,tick,nearest,ready,prompt,urgency} from './sim.js';
import {BallroomRenderer,CAST_STYLE,castWarningText} from './renderer.js';
import {TIERS,DEFAULT_TIER} from './difficulty.js';
import {scoreShift} from './score.js';
import {AudioDirector} from './audio.js';
const $=id=>document.getElementById(id),keys=new Set(),audio=new AudioDirector();
const SHIFT_SECONDS=180;
// Storage is a convenience: private windows and blocked site data must still play.
const store={get(key){try{return localStorage.getItem(key);}catch{return null;}},set(key,value){try{localStorage.setItem(key,value);}catch{}}};
const TIER_KEY='america.tier',bestKey=id=>'america.best.'+id;
let tierId=TIERS[store.get(TIER_KEY)]?store.get(TIER_KEY):DEFAULT_TIER,rating=null,lastThreats='';
let game=createGame(SHIFT_SECONDS,1,tierId),renderer,last=performance.now(),lastCaption=0,lastFx=0,speechTime=0,clickTarget=null,queuedE=false,queuedDash=false,interactHeld=false,loaded=false,shift=0,inspectorReturn=null;game.mode='start';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const displayGameText=text=>String(text).replace(/\bgoose\b/gi,w=>w===w.toUpperCase()?'DUCK':w[0]===w[0].toUpperCase()?'Duck':'duck');
function panel(title,body,buttons){$('overlay').classList.remove('hidden');$('overlay').innerHTML=`<div class="card"><div class="eyebrow">OFFICE OF ENTIRELY MANAGEABLE EVENTS</div><h2>${title}</h2>${body}<div class="actions">${buttons}</div></div>`;}
function startScreen(){renderer.inspecting=false;inspectorReturn=null;game.mode='start';keys.clear();interactHeld=false;clickTarget=null;audio.pause();document.body.classList.remove('live');panel('Six jobs. Zero dignity.',`<p>You are the last competent staffer in a ballroom full of very important puppets. Deliver the props, fix three room stations, keep the boss distracted, and survive <b>30 seconds of live television.</b></p><div class="pill">Real 3D puppets</div><div class="pill">Solo · one short shift</div><ul><li><b>Grab & go:</b> E picks up a colored prop. Carry it to its matching destination. Space dashes.</li><li><b>Fix the room:</b> hold E at the teleprompter, flags, and briefing cards. Stay still with empty hands.</li><li><b>Protect your work:</b> the boss, his cabinet and the lunch guests can undo it. Catch animals, recover dropped props, and press E near anyone mid-scheme to shoo him.</li><li><b>Everyone has a lure:</b> applause or ribbon for the boss, toy soldiers for Hegseth, the cozy couch for Vance, roadkill for RFK Jr.</li><li><b>Manners:</b> if Vance latches on, press E to say thank you.</li><li><b>Go live:</b> keep the microphone on, the boss off it, and the animals off camera.</li></ul><fieldset class="tiers"><legend>Difficulty · every shift is 3 minutes</legend>${Object.values(TIERS).map(t=>`<label class="tier"><input type="radio" name="tier" value="${t.id}" ${t.id===tierId?'checked':''}><span><b>${escape(t.label)}${t.multiplier>1?` · ×${t.multiplier} score`:''}</b>${escape(t.blurb)}</span></label>`).join('')}</fieldset><p class="note">WASD or arrows to move · tap the floor to walk · E to interact · Space to dash. Audio starts when you clock in.</p>`,`<button class="primary" id="start">Clock in →</button><button class="secondary" id="mixstart">Audio mix</button>`);$('start').onclick=()=>newShift(document.querySelector('input[name="tier"]:checked')?.value);$('mixstart').onclick=()=>settings('start');}
function newShift(id=tierId){tierId=TIERS[id]?id:DEFAULT_TIER;store.set(TIER_KEY,tierId);rating=null;renderer.resetFaces();renderer.inspecting=false;inspectorReturn=null;queuedE=false;queuedDash=false;game=createGame(SHIFT_SECONDS,++shift,tierId);lastCaption=0;lastFx=0;speechTime=0;clickTarget=null;keys.clear();interactHeld=false;audio.resetEvents();audio.resume();$('overlay').classList.add('hidden');$('speech').classList.remove('visible');}
function resume(){queuedE=false;queuedDash=false;game.mode='playing';$('overlay').classList.add('hidden');keys.clear();interactHeld=false;audio.resume();}
function pause(){if(!loaded)return;if(game.mode==='paused'){resume();return;}if(game.mode!=='playing')return;game.mode='paused';keys.clear();interactHeld=false;clickTarget=null;audio.pause();panel('Breathe. It’s on the clipboard.',`<p>The clock is paused. <b>E picks up and delivers. Hold E to work at room stations.</b> Match prop colors to destinations; watch the line on the floor. Space dashes every three seconds.</p><div class="tasklist">${game.deliveries.map(d=>`<div>${d.done?'✓':'□'} <b>${d.label}</b> → ${escape(d.target.short)}${d.displacedBy?' · needs recovery':''}</div>`).join('')}${roomJobs.map(j=>`<div>${game.tasks[j.id].done?'✓':'□'} <b>${j.label}</b> · ${jobStatus(game,j)}</div>`).join('')}<div>${game.micOn?'●':'○'} Microphone ${game.micOn?'ON':'OFF'} · applause buys 9 seconds · ribbon buys 7</div><div>During LIVE, earn ${game.show.required} clean seconds and resolve both incidents.</div></div><p class="note">Catch an animal with E while empty-handed, then carry it to the service exit. Bait can also lead both animals out. Repairing disrupted props costs nothing.</p>`,`<button class="primary" id="resume">Back to work</button><button class="secondary" id="mixpause">Audio mix</button><button class="secondary" id="restart">New shift</button>`);$('resume').onclick=resume;$('restart').onclick=startScreen;$('mixpause').onclick=()=>settings('paused');}
function settings(returnTo){if(!loaded)return;const was=returnTo||game.mode;if(game.mode==='playing'){game.mode='paused';keys.clear();interactHeld=false;audio.pause();}panel('A little less chaos. In your ears.',`<p>Music, sound effects and archival voice clips have separate controls.</p><div class="mixrow"><label for="musicvol">Music</label><input id="musicvol" type="range" min="0" max="100" value="${Math.round(audio.musicVolume*100)}"><output id="musicnum">${Math.round(audio.musicVolume*100)}</output></div><div class="mixrow"><label for="sfxvol">Effects</label><input id="sfxvol" type="range" min="0" max="100" value="${Math.round(audio.sfxVolume*100)}"><output id="sfxnum">${Math.round(audio.sfxVolume*100)}</output></div><div class="mixrow"><label for="voicevol">Archival voice</label><input id="voicevol" type="range" min="0" max="100" value="${Math.round((audio.voiceVolume??.8)*100)}"><output id="voicenum">${Math.round((audio.voiceVolume??.8)*100)}</output></div><label><input id="voiceenabled" type="checkbox" ${audio.voiceEnabled!==false?'checked':''}> Play cast voice clips</label><p class="note">Sourced public recordings are excerpted into this fictional parody. <a href="./credits.html" target="_blank">Recording sources</a>. Invented captions are not transcripts.</p>`,`<button class="primary" id="backmix">Done</button>`);for(const [id,fn,out]of [['musicvol','setMusicVolume','musicnum'],['sfxvol','setSfxVolume','sfxnum'],['voicevol','setVoiceVolume','voicenum']])$(id).oninput=e=>{$(out).textContent=e.target.value;audio[fn]?.(+e.target.value/100);};$('voiceenabled').onchange=e=>audio.setVoiceEnabled?.(e.target.checked);$('backmix').onclick=()=>{if(was==='start')startScreen();else if(['won','lost'].includes(was)){game.mode=was;finish();}else resume();};}
const castNames={trump:'TRUMP',staffer:'THE STAFFER','rfk-jr':'RFK JR',vance:'VANCE',hegseth:'HEGSETH',duck:'DUCK',raccoon:'RACCOON'};
function inspectCast(){if(!loaded||inspectorReturn!==null)return;for(const id of ['pause','settings','expand','cast-inspect'])$(id).disabled=true;inspectorReturn=game.mode;game.mode='paused';keys.clear();interactHeld=false;queuedE=false;queuedDash=false;clickTarget=null;audio.pause();renderer.inspecting=true;renderer.setPortrait('trump');panel('Very important faces. Unexpected lunch guests.',`<p>The shift is paused. Select a cast member to inspect the actual model and hear their sourced recordings. Duck and raccoon previews use their new 3D models.</p><div class="cast-buttons">${Object.entries(castNames).map(([id,name])=>`<button data-cast="${id}" class="${id==='trump'?'selected':''}">${name}</button>`).join('')}</div><div class="reaction-buttons"><button data-angle="0">Front view</button><button data-angle="0.55">Three-quarter view</button><button data-angle="1.25">Side view</button></div><div id="human-controls"><div class="reaction-buttons"><button data-reaction="neutral">Composed</button><button data-reaction="smile">Smug / delighted</button><button data-reaction="scowl">Annoyed</button><button data-reaction="surprise">Surprised</button><button data-reaction="worried">Panic at work</button></div><p class="note">Silent mouth test</p><div class="reaction-buttons">${['AA','EE','OO','FV','MBP','closed'].map(v=>`<button data-mouth="${v}">${v==='closed'?'Close mouth':v}</button>`).join('')}</div><p class="cast-preview-note">Their mouths follow each actual recording, closing during its pauses. The staffer is fictional and has no archival voice.</p><div id="voice-options" class="voice-options"></div><button id="stopclip" class="secondary">■ Stop clip</button><p class="note">Actual recordings are separate from invented game captions. <a href="./credits.html" target="_blank" rel="noopener">Recording sources</a>. Voice tests respect your sound settings.</p></div><p id="animal-note" class="note hidden">An actual textured 3D lunch guest with a suspicious amount of personality.</p>`,`<button class="primary" id="closecast">Done with the close-up</button>`);document.querySelectorAll('[data-cast]').forEach(button=>button.onclick=()=>{audio.stopVoice();renderer.mouthOverrides={};renderer.setPortrait(button.dataset.cast);document.querySelectorAll('[data-cast]').forEach(b=>b.classList.toggle('selected',b===button));inspectorVoices(button.dataset.cast);});document.querySelectorAll('[data-reaction]').forEach(button=>button.onclick=()=>renderer.previewReaction(renderer.portraitId,button.dataset.reaction,3));document.querySelectorAll('[data-mouth]').forEach(button=>button.onclick=()=>{audio.stopVoice();renderer.previewMouth(renderer.portraitId,button.dataset.mouth);});document.querySelectorAll('[data-angle]').forEach(button=>button.onclick=()=>{renderer.portraitAngle=+button.dataset.angle;});$('stopclip').onclick=()=>{renderer.mouthOverrides={};audio.stopVoice();};$('closecast').onclick=closeInspector;inspectorVoices('trump');}
function inspectorVoices(speaker){const animal=['duck','raccoon'].includes(speaker);$('human-controls').classList.toggle('hidden',animal);$('animal-note').classList.toggle('hidden',!animal);if(animal)return;const clips=audio.listVoices(speaker);$('voice-options').innerHTML=clips.length?clips.map(clip=>`<div class="voice-option"><button data-voice="${escape(clip.id)}">▶ ${escape(clip.label)}</button><span>${escape(clip.text||clip.label)}</span><a href="${escape(clip.sourceUrl)}" target="_blank" rel="noopener">Source recording ↗</a></div>`).join(''):'<p class="note">This staffer’s reactions are entirely fictional.</p>';document.querySelectorAll('[data-voice]').forEach(button=>button.onclick=()=>{const entry=audio.listVoices().find(e=>e.id===button.dataset.voice);renderer.mouthOverrides={};renderer.setPortrait(entry.speaker);renderer.previewReaction(entry.speaker,'smile',4);audio.playVoice(entry.id,{force:true,preview:true});});}
function closeInspector(){for(const id of ['pause','settings','expand','cast-inspect'])$(id).disabled=false;const was=inspectorReturn;inspectorReturn=null;renderer.inspecting=false;renderer.portraitAngle=0;renderer.mouthOverrides={};audio.stopVoice();audio.pause();queuedE=false;queuedDash=false;keys.clear();interactHeld=false;if(was==='playing')resume();else if(was==='paused'){game.mode='playing';pause();}else if(['won','lost'].includes(was)){game.mode=was;finish();}else startScreen();}
$('cast-inspect').onclick=inspectCast;
function portraitHud(state){const card=$('portrait').closest('.portrait-card');card.classList.toggle('speaking',!!state.playing);$('portrait-label').textContent=castNames[renderer.portraitId]||'PUPPET CAM';$('portrait-status').textContent=state.playing?'ARCHIVAL VOICE':renderer.inspecting?'CAST CLOSE-UP':'REACTION CAM';$('portrait-caption').textContent=state.playing?(state.text||state.label||'An archival interruption.'):({trump:'A face made for an unnecessary close-up.',staffer:'Paid by the hour. Aged by the minute.','rfk-jr':'Lunch may contain independent opinions.',vance:'His eyebrows have changed direction.',hegseth:'The briefing is taking this very seriously.',duck:'A very short neck. A very long incident report.',raccoon:'Lunch has accessed the event budget.'})[renderer.portraitId];}
$('exitfull').onclick=()=>{document.exitFullscreen?.();};$('expand').onclick=()=>{const stage=$('stage');if(document.fullscreenElement)document.exitFullscreen?.();else stage.requestFullscreen?.().catch(()=>{});};$('pause').onclick=pause;$('settings').onclick=()=>settings();$('sound').onclick=()=>{audio.setMuted(!audio.muted);$('sound').textContent=audio.muted?'♪ Sound off':'♪ Sound on';if(!audio.muted&&game.mode==='playing')audio.resume();};$('interact').onclick=()=>{if(game.mode==='playing')queuedE=true;};$('interact').onpointerdown=e=>{if(game.mode==='playing'){interactHeld=true;queuedE=true;e.currentTarget.setPointerCapture(e.pointerId);}};for(const event of ['pointerup','pointercancel','lostpointercapture'])$('interact').addEventListener(event,()=>{interactHeld=false;});$('dashbutton').onclick=()=>{if(game.mode==='playing')queuedDash=true;};
window.addEventListener('keydown',e=>{if(e.target.matches('input,select'))return;const k=e.key.toLowerCase();if(inspectorReturn!==null){if(k==='escape'){e.preventDefault();closeInspector();}return;}if(k==='escape'&&document.fullscreenElement){if(game.mode==='playing')pause();return;}if(['escape','p'].includes(k)){e.preventDefault();if(!e.repeat)pause();return;}if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(!e.repeat&&game.mode==='playing'){if(k==='e')queuedE=true;if(k===' ')queuedDash=true;}keys.add(k);if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright'].includes(k))clickTarget=null;});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();interactHeld=false;if(game.mode==='playing')pause();else if(inspectorReturn!==null)audio.pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden){keys.clear();interactHeld=false;if(game.mode==='playing')pause();else audio.pause();}});
$('game').addEventListener('pointerdown',e=>{if(game.mode!=='playing'||!renderer)return;const p=renderer.screenToFloor(e.clientX,e.clientY);clickTarget={x:Math.max(72,Math.min(1128,p.x)),y:Math.max(130,Math.min(690,p.y))};});
function input(){let up=keys.has('w')||keys.has('arrowup'),down=keys.has('s')||keys.has('arrowdown'),left=keys.has('a')||keys.has('arrowleft'),right=keys.has('d')||keys.has('arrowright');if(clickTarget){const dx=clickTarget.x-game.player.x,dy=clickTarget.y-game.player.y;if(Math.hypot(dx,dy)<12)clickTarget=null;else{left=dx<-8;right=dx>8;up=dy<-8;down=dy>8;}}const out={up,down,left,right,work:keys.has('e')||queuedE||interactHeld,dash:keys.has(' ')||queuedDash};queuedE=false;queuedDash=false;return out;}
function jobStatus(g,j){const t=g.tasks[j.id];if(t.done)return 'Ready';const stage=j.stages[Math.min(t.stage||0,j.stages.length-1)];return `${stage.label} · ${Math.min(100,Math.floor((t.progress||0)/stage.duration*100))}%`; }
function hud(){const g=game,live=g.show.phase==='live';$('clocklabel').textContent=live?'LIVE SHOT REMAINING':'CAMERAS ARRIVE IN';const seconds=Math.max(0,live?g.show.time:g.remaining);$('clock').textContent=`${Math.floor(seconds/60).toString().padStart(2,'0')}:${Math.floor(seconds%60).toString().padStart(2,'0')}`;$('patience').innerHTML=Math.ceil(g.patience)+'<span>%</span>';$('patiencebar').style.width=g.patience+'%';$('patiencebar').style.background=g.patience<35?'#b64032':'#3d9586';$('dash').textContent=g.dashCooldown>0?Math.ceil(g.dashCooldown)+'s':'READY ↗';$('budget').textContent='$'+g.budget+' budget';$('missionlabel').textContent=live?'MAKE SOME USABLE TELEVISION':'YOUR VERY SIMPLE JOB';$('progress').textContent=live?`${g.show.progress.toFixed(1)} / ${g.show.required}s clean airtime`:g.carry==='bait'?'Lead the animals to the service exit':g.carry?.startsWith('animal:')?'Carry your lunch guest to the service exit':g.carry==='packet'?'Bring the briefing to the service exit':g.work?roomJobs.find(j=>j.id===g.work.id)?.label+' · keep holding E':ready(g)?'Room ready. Clear the chaos or go live.':'Deliver 3 props · fix 3 room stations';$('hint').textContent=displayGameText(prompt(g));$('livebadge').classList.toggle('hidden',!live);$('airtime').textContent=`${g.show.progress.toFixed(1)} / ${g.show.required}s clean`;document.body.classList.toggle('live',live&&g.mode==='playing');document.body.classList.toggle('dash',g.dashTime>0);$('fullhud').textContent=`${live?'LIVE':'SHIFT'} ${Math.ceil(seconds)}s · PATIENCE ${Math.ceil(g.patience)}% · ${g.deliveries.filter(d=>d.done).length+roomJobs.filter(j=>g.tasks[j.id].done).length}/6 JOBS`; $('jobcount').textContent=`${g.deliveries.filter(d=>d.done).length+roomJobs.filter(j=>g.tasks[j.id].done).length} / 6 jobs · ${urgency(g)} urgent`;
 $('deliveries').innerHTML=g.deliveries.map(d=>`<div class="${d.done?'done':''}"><span class="swatch" style="background:${d.color}"></span><b>${d.done?'✓ ':g.carry===d.id?'CARRYING ':d.displacedBy?'↻ ':''}${d.label}</b><span>→ ${escape(d.target.short)}</span></div>`).join('');
 $('roomjobs').innerHTML=roomJobs.map(j=>{const t=g.tasks[j.id];return `<div class="${t.done?'done':''} ${g.work?.id===j.id?'working':''}"><span class="swatch" style="background:${j.color}"></span><b>${t.done?'✓ ':t.displacedBy?'↻ ':''}${j.label}</b><span>${escape(jobStatus(g,j))}</span></div>`;}).join('');
 const warnings=[];if(g.trump.phase==='tampering')warnings.push(`<div class="incident"><b>! BOSS IS "IMPROVING" IT</b>${Math.ceil(g.trump.timer)}s to distract him · E nearby to shoo · or applause / ribbon</div>`);else if(g.warning?.kind==='tamper')warnings.push(`<div class="incident warning"><b>HE'S HEADING FOR YOUR WORK</b>Get close and E to shoo, or trigger applause.</div>`);else if(g.trump.phase==='talking')warnings.push(`<div class="incident"><b>THE BOSS HAS THE MIC</b>Cut the mic, trigger applause, or start the ribbon ceremony.</div>`);for(const i of g.incidents.filter(i=>!i.resolved))warnings.push(`<div class="incident"><b>${escape(i.label)}</b>${i.id==='lunch'?'Catch with E → carry to exit, or use bait':'Briefing desk → service exit'}</div>`);if(g.vance.phase==='active')warnings.push('<div class="incident warning"><b>DIRECTIONS HAVE CHANGED</b>Follow the matching prop color.</div>');$('incidents').innerHTML=warnings.slice(0,3).join('');
 // Overlapping cast telegraphs stay readable here even after the caption has moved on.
 const threats=g.mode==='playing'?g.castWarnings.map(w=>`<div class="threat" style="--who:${CAST_STYLE[w.who].color}"><b>${CAST_STYLE[w.who].name}</b>${castWarningText(w)}</div>`).join(''):'';if(threats!==lastThreats){lastThreats=threats;$('threats').innerHTML=threats;}
}
// Best scores only count finished broadcasts; a cancelled show still shows its points.
function recordBest(){const tier=game.tier,result=scoreShift(game),previous=Number(store.get(bestKey(tier.id)))||0,isNew=game.mode==='won'&&result.points>previous;if(isNew)store.set(bestKey(tier.id),String(result.points));return{result,tier,best:Math.max(previous,isNew?result.points:0),isNew};}
function ratingCard({result:r,tier,best,isNew}){return `<div class="rating"><div class="grade${r.grade==='CANCELLED'?' cancelled':''}">${r.grade}</div><div><b class="headline">${escape(r.headline)}</b><div class="points">${r.points.toLocaleString()} points${r.multiplier!==1?` <small>${r.base.toLocaleString()} × ${r.multiplier} ${escape(tier.label)}</small>`:''}</div><div class="best">Best on ${escape(tier.label)}: ${best.toLocaleString()}${isNew?' <span class="newbest">NEW BEST</span>':''}</div></div></div><div class="breakdown">${r.breakdown.map(b=>`<div><span>${escape(b.label)}</span><b>${b.value>0?'+':''}${b.value.toLocaleString()}</b></div>`).join('')}</div>`;}
function finish(){keys.clear();interactHeld=false;clickTarget=null;const win=game.mode==='won';rating||=recordBest();panel(win?'Thirty seconds. Somehow, television.':'Everything was briefly fine.',`<p>${win?'All six room jobs finished, the guests safely escorted out, and enough clean airtime to look organized. Naturally, he takes all the credit.':escape(game.lossReason||'The cameras arrived before the room was ready.')}</p>${ratingCard(rating)}<p class="note">${win?'Your reward: another event.':'Tip: keep the mic off while delivering. Turn it on for the broadcast, then use the lures to keep everyone busy.'}</p>`,`<button class="primary" id="again">One more shift →</button><button class="secondary" id="menu">Clipboard</button>`);$('again').onclick=()=>newShift();$('menu').onclick=startScreen;}
function frame(now){const dt=Math.min((now-last)/1000,.06);last=now;const before=game.mode;tick(game,dt,input());if(game.eventId!==lastCaption&&game.event){lastCaption=game.eventId;$('speech').textContent=displayGameText(game.event);$('speech').classList.add('visible');speechTime=5;}if(game.mode==='playing')speechTime-=dt;if(speechTime<=0)$('speech').classList.remove('visible');if(game.mode==='playing'||before==='playing')audio.updateGameEvents(game.events);for(const e of game.events){if(e.id>lastFx){renderer.effect(e.type,game.player);renderer.react(e);lastFx=e.id;}}if(before==='playing'&&['won','lost'].includes(game.mode))finish();audio.syncGame?.(game);audio.tick();const voiceState=audio.getVoiceState();renderer.setVoiceState(voiceState);renderer.render(game,dt);portraitHud(voiceState);hud();window.__america={game,renderer,audio,loaded,version:'3d-v6-chaos-cast'};requestAnimationFrame(frame);}
try{renderer=new BallroomRenderer($('game'),$('portrait'));renderer.load((p,id)=>{$('loadbar').style.width=`${Math.round(p*100)}%`;$('loadlabel').textContent=`${Math.round(p*100)}% · ${({'staffer':'Your exhausted staffer',trump:'The boss',vance:'The directions department','rfk-jr':'The lunch host',hegseth:'The briefing department',Duck:'The lunch guest with a bill',Raccoon:'The masked event planner',goose:'The duck',raccoon:'The raccoon'})[id]||'The puppets are arriving'}`;renderer.render(game,0);}).then(()=>{loaded=true;$('modelstatus').textContent='Five textured 3D puppets + two wildlife guests';startScreen();requestAnimationFrame(frame);}).catch(error=>{console.error(error);panel('The guests are delayed.',`<p>${escape(error.message||'A cast member or lunch guest could not arrive.')} Check your connection and reload the ballroom.</p>`,`<button class="primary" id="reload">Try again</button>`);$('reload').onclick=()=>location.reload();});}catch(error){console.error(error);panel('This ballroom needs a little more graphics power.','<p>Your browser could not open the 3D room. Try a recent desktop browser with hardware acceleration enabled.</p>','<button class="primary" id="reload">Try again</button>');$('reload').onclick=()=>location.reload();}
